import { exportExecl } from '@/utils'
import { ActionType, ProColumns, ProFormInstance, ProTable, ProTableProps } from '@ant-design/pro-components'

// 扩展的 ref 类型
export type ExcelTableActionType = ActionType & {
  setFieldsValue?: (values: any) => void
  submit?: () => void
  getFieldsValue?: () => any
}
import { Button, Card } from 'antd'
import { forwardRef, useRef, useState, useEffect, useImperativeHandle } from 'react'
import type { FC } from 'react'
import { ResultEnum } from '@/utils/enums/httpEnum'

type IExcelTable = {
  columns: ProColumns<any, 'text'>[]
  /** 接口请求 */
  requestFn: (params: any, sort?: any) => any
  /** 导出接口 */
  exportExeclReq?: (params: any) => any
  /** toolBarRender */
  toolBarRenderFn?: (params: any) => any
  ref?: any
  /** 设置选择的row */
  setSelectedRows?: React.Dispatch<React.SetStateAction<any[]>>
  /** 自定义导出 */
  customExport?: (params: any) => any
  /** 额外的勾选属性 */
  extraRowSelection?: Record<string, any>
  /** 初始值key选择 */
  initRowKey?: any[]
  /** 自定义state key */
  customKeys?: any[]
  setCustomKeys?: React.Dispatch<React.SetStateAction<any[]>>
  rowKey?: string
} & ProTableProps<any, any>

const ExcelTable: FC<IExcelTable> = forwardRef((props, formRefMy: any) => {
  const {
    columns,
    requestFn,
    exportExeclReq,
    toolBarRenderFn,
    setSelectedRows,
    customExport,
    extraRowSelection,
    initRowKey,
    customKeys,
    setCustomKeys,
    rowKey,
    ...otherProps
  } = props
  const [selectedRowKeys, setSelectedRowKeys] = useState<any>(initRowKey || [])
  const formRefin = useRef<ProFormInstance | undefined>(undefined)

  const onSelectChange = (rowKeys: any[], selectedRows: any[]) => {
    setSelectedRowKeys(rowKeys)
    if (setCustomKeys) {
      setCustomKeys(rowKeys)
    }

    if (setSelectedRows) {
      setSelectedRows(selectedRows)
    }
  }

  /** 自定义state key 赋予初始值 */
  useEffect(() => {
    if (initRowKey && setCustomKeys) {
      setCustomKeys(initRowKey)
    }
    if (initRowKey && setSelectedRows) {
      setSelectedRows(
        initRowKey?.map(item => ({
          id: item
        }))
      )
    }
  }, [initRowKey])

  const onExport = async () => {
    if (customExport) {
      customExport({
        record: formRefin?.current?.getFieldsValue(),
        id__in:
          (customKeys || selectedRowKeys)?.length > 0
            ? (customKeys || selectedRowKeys)?.join?.(',')
            : undefined
      })
    } else {
      const data = await exportExeclReq?.({
        formData: formRefin?.current?.getFieldsValue(),
        is_export: true,
        id__in:
          (customKeys || selectedRowKeys)?.length > 0
            ? (customKeys || selectedRowKeys)?.join?.(',')
            : undefined
      })
      exportExecl(data)
    }
  }

  useImperativeHandle(formRefMy, () => ({
    onExport: () => onExport(),
    setFieldsValue: (values: any) => formRefin?.current?.setFieldsValue?.(values),
    submit: () => formRefin?.current?.submit?.(),
    getFieldsValue: () => formRefin?.current?.getFieldsValue?.()
  }))

  return (
    <Card>
      <ProTable
        columns={columns}
        formRef={formRefin}
        request={async (params = {}, sort) => {
          const { current: page, pageSize, ...otherParams } = params
          const res = await requestFn({ page, pageSize, ...otherParams }, sort)
          if (res?.code === ResultEnum.SUCCESS) {
            return {
              total: res?.data?.totalCount,
              data: res?.data?.list,
              success: true,
              page: res?.data?.page
            }
          }
          return {
            success: false
          }
        }}
        rowKey={rowKey ? rowKey : 'id'}
        rowSelection={{
          // 自定义选择项参考: https://ant.design/components/table-cn/#components-table-demo-row-selection-custom
          // 注释该行则默认不显示下拉选项
          //   selections: [Table.SELECTION_ALL, Table.SELECTION_INVERT],
          preserveSelectedRowKeys: true,
          selectedRowKeys: customKeys || selectedRowKeys,
          onChange: onSelectChange,
          ...extraRowSelection
        }}
        search={{
          defaultCollapsed: false,
          // span: 6,
          // labelWidth: 80,
          optionRender: (searchConfig, formProps, dom) => [
            dom[1],
            <Button
              key="reset"
              onClick={() => {
                const keyArr = (searchConfig as any)?.items?.map(
                  (item: { props: { name: any } }) => [item?.props?.name, undefined]
                )
                formProps?.form?.setFieldsValue(Object.fromEntries(new Map(keyArr).entries()))
                formProps?.form?.submit()
              }}
            >
              重置
            </Button>
          ]
        }}
        bordered
        form={{
          className: 'table-search-from',
          // 由于配置了 transform，提交的参与与定义的不同这里需要转化一下
          // syncToUrl: (values, type) => {
          //   if (type === 'get') {
          //     // return {
          //     //   ...values
          //     //   // created_at: [values.startTime, values.endTime],
          //     // }
          //     // 过滤掉分页参数
          //     const { current, pageSize, ...rest } = values
          //     return rest // 仅同步其他搜索参数
          //   }
          //   return values
          // }
          syncToUrl: false
        }}
        pagination={{
          showSizeChanger: true
        }}
        dateFormatter="string"
        toolBarRender={
          toolBarRenderFn || exportExeclReq
            ? () => [
                exportExeclReq && (
                  <Button
                    key="export-button" // 使用语义化key替代字符串key
                    onClick={onExport}
                    type="primary"
                  >
                    导出数据
                  </Button>
                ),
                ...(toolBarRenderFn?.({ rowKeys: customKeys || selectedRowKeys }) || [])
              ]
            : false
        }
        {...otherProps}
      />
    </Card>
  )
})

export default ExcelTable
